# -*- coding: utf-8 -*-
from lesson_authoring import entry as E
from author_batch200_root_bio_a import B,H
BA=B+[['英语 bio- + accumulation → bioaccumulation；相应动词 bioaccumulate','物质在生物体内随时间累积']]
WG=[
E('biofuel','英 /ˈbaɪəʊfjuːəl/；美 /ˈbaɪoʊfjuːəl/','生物燃料','把较近期生物产生的材料，转成能供使用的燃料。','bio-“生物来源” + fuel“燃料”，现代能源构词。',H(B,'英语 bio- + fuel → biofuel','由生物质制成的燃料'),'乙醇燃料、生物柴油等常被归入 biofuels。这个类别强调原料来源；其实际环境影响仍与种植、加工、运输等有关。煤和石油虽也有远古生命来源，却通常归为化石燃料，不叫 biofuel。','produce biofuel；biofuel production；a biofuel blend。','biofuel 是燃料产品；biomass 是可作为原料的生物质，也可有生态学的生物量义。',('The facility produces biofuel from plant material.','这座设施用植物材料生产生物燃料。'),('The report compares several types of biofuel.','报告比较了几种生物燃料。'),sources=['https://en.wiktionary.org/wiki/biofuel','https://www.eia.gov/energyexplained/biofuels/']),
E('biodiesel','英 /ˌbaɪəʊˈdiːzəl/；美 /ˌbaɪoʊˈdiːzəl/','生物柴油','用油脂等生物原料加工出可用于柴油燃料体系的一类燃料。','bio-“生物来源” + diesel“柴油”，这里是来源与用途相关名称的组合。',H(B,'英语 bio- + diesel → biodiesel','由生物油脂等原料加工的柴油类燃料'),'biodiesel 常由植物油、动物脂肪或废油脂等加工而来，可与石油柴油调配使用。它不是把普通食用油直接倒进发动机。renewable diesel 也可用相近原料，但生产路线和化学组成不同，技术文章会区分两者。','biodiesel production；a biodiesel blend；biodiesel fuel。','biodiesel 与 renewable diesel 并非技术上完全相同的词；biofuel 则是更大的类别。',('The company produces biodiesel from used cooking oil.','公司用废弃食用油生产生物柴油。'),('The study compared biodiesel with conventional diesel fuel.','研究比较了生物柴油与传统柴油。'),sources=['https://en.wiktionary.org/wiki/biodiesel','https://www.eia.gov/energyexplained/biofuels/biodiesel-rd-other-basics.php']),
E('biogas','英 /ˈbaɪəʊɡæs/；美 /ˈbaɪoʊɡæs/','沼气；生物气','有机物被微生物分解时，产生一股含可燃成分的气体。','bio-“生物过程” + gas“气体”，现代能源词。',H(B,'英语 bio- + gas → biogas','生物分解过程产生的混合气体'),'biogas 常由有机物在缺氧条件下被微生物分解而产生，主要含甲烷和二氧化碳，也会有其他成分。它经过进一步处理可用于能源用途。原始 biogas 不等于纯甲烷，也不与提纯后的 biomethane 完全等同。','produce biogas；a biogas plant；biogas production。','biogas 是混合气体；biomethane 通常强调富集、提纯后的甲烷成分。',('The facility captures biogas from organic waste.','这座设施收集有机废物产生的沼气。'),('Biogas can be used to generate electricity.','沼气可用于发电。'),sources=['https://en.wiktionary.org/wiki/biogas','https://www.eia.gov/energyexplained/biomass/landfill-gas-and-biogas.php']),
E('biohazard','英 /ˈbaɪəʊhæzəd/；美 /ˈbaɪoʊˌhæzərd/','生物危害；具有生物危害的材料或因素','危险来自生物因子或相关材料，而不只是电、热或机械力。','bio-“生物” + hazard“危害因素”，现代安全术语。',H(B,'英语 bio- + hazard → biohazard','来自生物因子的潜在危害'),'biohazard 可以指潜在感染性材料、某些生物毒素等相关危害。标志提示需要按相应要求处理，并不是说一看见标志就已发生感染。hazard 强调危害源，具体风险还取决于暴露情境。','a biohazard warning；biohazard waste；a potential biohazard。','biohazard 是危害源或材料；biosafety 是预防相关意外伤害的管理与实践。',('The container carries a biohazard warning.','容器上贴着生物危害警示。'),('The assessment identified a potential biohazard.','评估识别出了一项潜在生物危害。'),sources=['https://en.wiktionary.org/wiki/biohazard','https://www.merriam-webster.com/dictionary/biohazard']),
E('biohazardous','英 /ˌbaɪəʊˈhæzədəs/；美 /ˌbaɪoʊˈhæzərdəs/','有生物危害的','用一个形容词说明：这种材料带有需要管理的生物危害。','biohazard 与 -ous 形容词形式相接，也可看作 bio- + hazardous。',B+[['英语 biohazard／hazardous 词族 → biohazardous','生物危害 → 具有生物危害的']],'biohazardous waste 指带有相应生物危害的废物，不是所有来自生物的垃圾。这个形容词没有给出统一的危害等级，实际分类仍依材料性质和处理情境而定。','biohazardous waste；biohazardous material；biohazardous substances。','biological 只说与生物有关；biohazardous 明确增加了危害性质，不能互换。',('The waste was classified as biohazardous.','这些废物被归类为具有生物危害的废物。'),('Only authorized staff entered the area containing biohazardous materials.','只有获授权的工作人员进入了存有生物危害材料的区域。'),sources=['https://en.wiktionary.org/wiki/biohazardous','https://www.merriam-webster.com/dictionary/biohazardous']),
E('biosafety','英 /ˌbaɪəʊˈseɪfti/；美 /ˌbaɪoʊˈseɪfti/','生物安全；防止生物相关意外暴露或释放的措施与实践','让人和环境免于工作过程中的意外生物伤害。','bio-“生物” + safety“安全”，现代研究与防护词汇。',H(B,'英语 bio- + safety → biosafety','围绕生物活动与材料的安全实践'),'实验室语境中 biosafety 重点预防意外暴露和意外释放，涉及风险评估、设施、设备与工作实践。它不是单指一件防护服，也不只是实验开始前填一张表，而是贯穿工作的安全管理。','laboratory biosafety；biosafety training；a biosafety assessment。','在实验室语境中，biosecurity 更强调防止未经授权获取、丢失或蓄意滥用；biosafety 更强调意外风险。',('All new staff completed biosafety training.','所有新员工都完成了生物安全培训。'),('The project included a biosafety assessment.','项目包含了一项生物安全评估。'),sources=['https://www.merriam-webster.com/dictionary/biosafety','https://ihrbenchmark.who.int/document/glossary']),
E('bioterrorism','英 /ˌbaɪəʊˈterərɪzəm/；美 /ˌbaɪoʊˈterərɪzəm/','生物恐怖主义；利用生物因子实施恐怖活动','把生物危害当成蓄意伤害和制造恐惧的工具。','bio-“生物” + terrorism“恐怖主义”，现代公共安全词汇。',H(B,'英语 bio- + terrorism → bioterrorism','以生物因子进行的恐怖活动'),'这个词强调蓄意行为及恐怖活动目的，不是自然发生的疾病暴发，也不是任何实验室意外的同义词。公共卫生文章常讨论如何识别、应对和恢复，词义本身不说明某次事件已被确认属于这一类。','bioterrorism preparedness；a suspected bioterrorism incident；responses to bioterrorism。','outbreak 是疾病暴发，本身不说明来源或动机；bioterrorism 则包含蓄意恐怖行为这一判断。',('The exercise tested preparedness for a bioterrorism incident.','这次演练测试了对生物恐怖事件的准备能力。'),('The article distinguishes natural outbreaks from bioterrorism.','文章区分了自然暴发与生物恐怖活动。'),sources=['https://en.wiktionary.org/wiki/bioterrorism','https://stacks.cdc.gov/view/cdc/44106','https://www.cdc.gov/field-epi-manual/php/chapters/biologic-toxic-agents.html']),
E('biocide','英 /ˈbaɪəʊsaɪd/；美 /ˈbaɪəˌsaɪd/','杀生剂；杀灭或抑制生物的物质','目标是压制某些生物的生长或活动，而不是给它们补充养分。','bio-“生命” + -cide“杀灭”，近代科学组合；实际类别也可包括抑制作用。',H(B,'近代 bio- + -cide → biocide','杀灭或抑制生物的物质'),'biocide 可涵盖杀藻、杀真菌等用途的物质。名字里的“杀”提示作用方向，不意味着一种产品能杀灭所有生物，也没有说明具体适用场合。它与带 bio- 的“环保、天然”印象尤其不同。','a chemical biocide；the effects of a biocide；biocide resistance。','biocide 范围较广；antibiotic 在普通医疗语境中主要说抗细菌药物。并非每种杀生剂都是抗生素。',('The study examined the biocide’s effects on algae.','研究考察了这种杀生剂对藻类的影响。'),('The researchers compared two biocides.','研究者比较了两种杀生剂。'),sources=['https://www.merriam-webster.com/dictionary/biocide','https://en.wiktionary.org/wiki/biocide']),
E('biocidal','英 /ˌbaɪəʊˈsaɪdəl/；美 /ˌbaɪoʊˈsaɪdəl/','杀生的；能杀灭或抑制生物的','把 biocide 的作用变成形容词：这种性质或处理会压制目标生物。','与 biocide 对应的 -al 形容词形式，保留 bio- 与 -cid- 的组合。',B+[['近代 biocide 词族 → biocidal','杀生剂 → 具有杀生作用的']],'biocidal activity 指材料或物质表现出的杀灭、抑制生物能力。评价时要说明针对什么生物以及怎样测量；这个形容词不自动等于适合接触人体。','biocidal activity；biocidal properties；a biocidal product。','biocidal 关注对目标生物的作用；biocompatible 关注特定生物应用中的相容性，方向和判据不同。',('The material showed biocidal activity in the test.','这种材料在测试中表现出了杀生作用。'),('The paper compares the biocidal properties of the coatings.','论文比较了这些涂层的杀生性能。'),sources=['https://en.wiktionary.org/wiki/biocidal','https://www.merriam-webster.com/dictionary/biocidal']),
E('bioaccumulate','英 /ˌbaɪəʊəˈkjuːmjʊleɪt/；美 /ˌbaɪoʊəˈkjuːmjəleɪt/','在生物体内累积；使物质在体内累积','进来的量长期多于清出去的量，身体里留下的就越来越多。','bio-“生物体内” + accumulate“累积”；是 bioaccumulation 词族的动词，不据拆分断言它先于名词。',H(BA,'英语 bioaccumulate','在生物体内逐渐累积'),'a chemical can bioaccumulate in fish 说化学物质会在鱼体内累积；fish can bioaccumulate a chemical 则把鱼放到主语位置。两种结构说的是同类现象，并不要求物质沿食物链逐级放大。','bioaccumulate in tissue；chemicals that bioaccumulate；organisms bioaccumulate substances。','bioaccumulate 关注一个生物体内随时间的累积；biomagnify 关注食物链较高营养级中浓度的增加。',('The substance can bioaccumulate in fish.','这种物质能够在鱼体内累积。'),('Some organisms bioaccumulate contaminants from their environment.','一些生物会把环境中的污染物累积在体内。'),sources=['https://www.merriam-webster.com/dictionary/bioaccumulation','https://archive.epa.gov/region5/superfund/ecology/web/html/glossary.html']),
E('bioaccumulation','英 /ˌbaɪəʊəˌkjuːmjʊˈleɪʃən/；美 /ˌbaɪoʊəˌkjuːmjəˈleɪʃən/','生物累积','一次进入的量可能不多，但排出或分解跟不上，时间久了就积起来。','bio-“生物体内” + accumulation“累积”，现代环境科学名词。',BA,'bioaccumulation 可以涉及从水、食物或其他环境来源进入体内的物质。它强调净累积过程，不是只要测到一点物质就说明浓度必然一直上升。具体变化还受摄入、排出、代谢等因素影响。','bioaccumulation in organisms；the potential for bioaccumulation；bioaccumulation of contaminants。','bioaccumulation 与 biomagnification 不完全相同：前者看体内积累，后者看食物网传递中的浓度放大。',('The study assessed the potential for bioaccumulation.','研究评估了发生生物累积的可能性。'),('Bioaccumulation can change the concentration of a substance in tissues over time.','生物累积会使组织中某种物质的浓度随时间变化。'),sources=['https://www.merriam-webster.com/dictionary/bioaccumulation','https://archive.epa.gov/region5/superfund/ecology/web/html/glossary.html']),
E('bioremediation','英 /ˌbaɪəʊrɪˌmiːdiˈeɪʃən/；美 /ˌbaɪoʊrɪˌmiːdiˈeɪʃən/','生物修复','借助生物活动，帮助污染环境恢复，而不是只把污染物搬到另一处。','bio-“生物作用” + remediation“修复、补救”，现代环境治理构词。',H(B,'英语 bio- + remediation → bioremediation','利用生物活动处理环境污染'),'bioremediation 常利用微生物分解或转化污染物，也可能涉及植物等生物。不同污染物和环境条件适用方法不同；某些物质能被降解，某些只能被转化、固定或移除，不能一概说“吃掉就消失”。','bioremediation of soil；a bioremediation project；microbial bioremediation。','biodegradation 是分解过程；bioremediation 是利用相关生物过程实现环境修复的应用。',('The site was selected for a bioremediation study.','这个场地被选作生物修复研究地点。'),('The project used bioremediation to reduce contamination in the soil.','项目利用生物修复减少土壤污染。'),sources=['https://en.wiktionary.org/wiki/bioremediation','https://nepis.epa.gov/Exe/ZyPURL.cgi?Dockey=P100F9WC.TXT','https://sor.epa.gov/sor_internet/registry/termreg/searchandretrieve/glossariesandkeywordlists/search.do?details=&vocabName=Terms+of+Env+%282009%29']),
]
